private void UpdateClassInfo(bool bolShowSubjectCount)
{
    string strRegulation = "--";
    if (uClass.RegulationID != null)
    {
        int intRegulationID = uClass.RegulationID.Value;
        string strLoai = "Niên chế";
        if (intRegulationID == 44 || intRegulationID == 99 || intRegulationID == 43)
            strLoai = "Tín chỉ";
        strRegulation = String.Format("{0} ({1})", intRegulationID, strLoai);
    }

    string strSubjectCount = "--";
    if (bolShowSubjectCount && dtbClassSubject != null)
        strSubjectCount = dtbClassSubject.Rows.Count.ToString();

    lblClassInfo.Text = String.Format("Quy chế: {0}\r\nSố môn: {1}", strRegulation, strSubjectCount);
}

